def flash_block_max(current_max, new_score):
    if new_score > current_max:
        return new_score
    return current_max



def flash_block_sum_exp(current_sum, old_max, new_max, new_score):
    rescale = math.exp(old_max - new_max)
    return current_sum * rescale + math.exp(new_score - new_max)



def flash_block_output(current_output, old_max, new_max, attention_weight, value):
    rescale = math.exp(old_max - new_max)
    return current_output * rescale + attention_weight * value



def flash_rescale_output(output, old_sum, old_max, new_max):
    if old_sum <= 0.0:
        return output
    return output * math.exp(old_max - new_max)



def flash_final_normalize(output, normalizer):
    if normalizer <= 0.0:
        return 0.0
    return output / normalizer



def paged_attention_block_score(query_elem, key_elem, block_max_key, head_dim):
    if head_dim <= 0.0:
        return 0.0
    return (query_elem * key_elem) / math.sqrt(head_dim)



def sliding_window_attention(query_pos, key_pos, window_size):
    dist = query_pos - key_pos
    if dist < 0.0:
        dist = -dist
    if dist <= window_size and key_pos <= query_pos:
        return 0.0
    return -1e9



def sparse_attention_block_density(n_attended, block_size):
    max_attended = block_size * block_size
    if max_attended <= 0.0:
        return 1.0
    return n_attended / max_attended



def grouped_query_attention_scale(n_query_heads, n_kv_heads):
    if n_kv_heads <= 0.0:
        return n_query_heads
    return n_query_heads / n_kv_heads



def ring_attention_chunk_size(seq_len, n_devices):
    if n_devices <= 0.0:
        return seq_len
    return seq_len / n_devices
